def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a 2D table to store the results of sub-problems
    dp = [[0 for _ in range(n + 1)] for _ in range(V + 1)]

    # Fill the table with 0s
    for i in range(V + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0

    # Fill the table in a bottom-up manner using the recurrence relation
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            if volumes[j - 1] <= i:
                dp[i][j] = max(dp[i - volumes[j - 1]][j - 1], dp[i][j - 1])
            else:
                dp[i][j] = dp[i][j - 1]

    # Return the minimum remaining space
    return V - dp[V][n]
```

