def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0
    left = [[] for _ in range(n)]
    right = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if heights[i] < heights[j]:
                left[i].append(j)
            elif heights[i] > heights[j]:
                right[i].append(j)
    result = 0
    visited = [False for _ in range(n)]
    def dfs(i, path):
        nonlocal result
        if len(path) == n // 2:
            result = max(result, len(path))
            return
        for j in left[i]:
            if not visited[j]:
                visited[j] = True
                dfs(j, path + [j])
                visited[j] = False
        for j in right[i]:
            if not visited[j]:
                visited[j] = True
                dfs(j, path + [j])
                visited[j] = False
    dfs(0, [0])
    return n - result
```

